const beforeSalaryAuto=autoVariables;
autoVariables=function(v){const out=beforeSalaryAuto(v);if(v.baseMode==='Horaire'||v.salaryMode!=='Automatique entrée / sortie')return out;const r=SalaryProration.calculate(v,v.leaveCurrentPeriod||period());return{...out,base:r.base.toFixed(2),salaryMonthHours:r.totalHours.toFixed(2),salaryContractHours:r.contractHours.toFixed(2),salaryOutsideHours:r.outsideHours.toFixed(2),salaryProrataDeduction:r.deduction.toFixed(2),salaryProrataApplied:r.applied,salaryCalculation:`${euroFmt(r.monthly)} × ${r.contractHours} h / ${r.totalHours} h = ${euroFmt(r.base)}`};};
const beforeSalaryRich=richVar;
richVar=function(p){const v=beforeSalaryRich(p);const out={salaryMode:'Automatique entrée / sortie',salaryHoursMode:'Calendrier',salaryNonWorkedDates:'',salaryMonthHours:'',salaryContractHours:'',...v,salaryStart:p.startDate||v.salaryStart||'',salaryEnd:p.actualEndDate||v.exitDate||(p.contract==='CDD'?p.endDate:'')||v.salaryEnd||''};try{return autoVariables(out)}catch(e){return{...out,base:'',salaryProrationError:e.message}}};
const beforeSalaryMarkup=variableMarkup;
variableMarkup=function(p){const v=richVar(p);return beforeSalaryMarkup(p)+section('Salaire de base · prorata entrée / sortie',selectField('salaryMode','Salaire mensuel à payer',v.salaryMode,['Automatique entrée / sortie','Montant fourni'])+field('salaryStart','Date d’entrée retenue pour le salaire',v.salaryStart,'date')+field('salaryEnd','Date de fin retenue pour le salaire (si connue)',v.salaryEnd,'date')+selectField('salaryHoursMode','Horaire réel servant au prorata',v.salaryHoursMode,['Calendrier','Horaires fournis'])+field('salaryMonthHours','Heures prévues pour le mois complet — horaire réel',v.salaryMonthHours,'number','min="0" step=".01"')+field('salaryContractHours','Heures prévues entre entrée et sortie dans le mois',v.salaryContractHours,'number','min="0" step=".01"')+field('salaryNonWorkedDates','Dates hors horaire à exclure (AAAA-MM-JJ, séparées par virgules)',v.salaryNonWorkedDates)+`<p class="wide notice" id="salaryCalculationLive" aria-live="polite"></p><p class="wide muted">Salaire mensuel contractuel × heures prévues sous contrat / horaire réel du mois complet. Le planning hebdomadaire est celui de la section congés : adaptez-le au contrat. L’horaire mensuel contractuel de 151,67 h et le taux horaire arrondi ne servent pas de diviseur au prorata. Jours fériés, cycles particuliers ou horaires irréguliers : vérifiez l’horaire ou utilisez « Horaires fournis ». Le prorata ne réduit pas une seconde fois les heures en mode Horaire. Ne ressaisissez pas la réduction d’entrée/sortie dans la retenue manuelle d’absence. Autres absences, HS et primes restent traitées séparément. « Montant fourni » conserve le montant mensuel saisi sans prorata.</p>`);};
const beforeSalaryRead=readVariableForm;
readVariableForm=function(f){const v=beforeSalaryRead(f);return autoVariables(v);};
const beforeSalaryRefresh=refreshCalculations;
refreshCalculations=function(){beforeSalaryRefresh();const f=$('#form'),out=$('#salaryCalculationLive');if(!out)return;for(const k of ['salaryMonthHours','salaryContractHours'])f.elements[k].readOnly=f.elements.salaryHoursMode.value==='Calendrier';try{const v=autoVariables(Object.fromEntries(new FormData(f)));for(const k of ['base','salaryMonthHours','salaryContractHours'])if(v[k]!==undefined)f.elements[k].value=v[k];out.textContent=v.baseMode==='Horaire'?'Mode horaire : heures normales × taux, sans second prorata.':v.salaryMode==='Automatique entrée / sortie'?v.salaryCalculation:'Montant fourni : aucun prorata automatique.';$('#grossLive').textContent=autoSummary(v);}catch(e){out.textContent=e.message;$('#grossLive').textContent='À compléter';}};
render();
